result:
.fill {
  width: 100%;
  height: 100%;
}

.content-box {
  width: calc(100% - 16px);
  height: calc(100vh - 96px);
  padding: 16px 24px 16px 14px;
  background: #fff;
  overflow: auto;
  border-radius: 4px;
}

.content-body {
  width: 100%;
  height: calc(100% - 95px);
  position: relative;
}

.empty-text {
  display: flex;
  justify-content: center;
  align-content: center;
  align-items: center;
  line-height: 60px;
  color: #909399;
}

.table-link-text {
  display: block;
  width: 100%;
  height: 100%;
  color: #2794f8;
  cursor: pointer;
}

.lcdp-dialog ::v-deep .el-dialog {
  width: 970px;
  height: 60%;
  min-height: 500px;
}

.lcdp-dialog ::v-deep .el-dialog__title {
  color: #333651;
}

::v-deep .el-dialog__body {
  padding: 21px 24px 12px 24px;
  width: 100%;
  height: calc(100% - 42px);
}

.dialog-title {
  line-height: 22px;
  font-size: 16px;
  color: #333651;
  display: inline-block;
  vertical-align: middle;
}

.limit-title-length {
  max-width: 450px;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  word-break: break-all;
}
